/// First-chunk header of a format = 4 (MagLS filters) CLIP_CHUNK payload.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct MaglsHeader {
    /// MAGLS_MAGIC, 'MYBD'
    pub magic: u32,
    /// MAGLS_VERSION (1)
    pub version: u32,
    /// ambisonic order, 3
    pub order: u32,
    /// taps per response: MAGLS_TAPS (256) at up to 48 kHz, MAGLS_TAPS_HIGH_RATE (512) above 88.2 kHz
    pub taps: u32,
    /// the rate of the responses (the context rate)
    pub sample_rate: f32,
    pub reserved: [u32; 3],
}

impl MaglsHeader {
    pub const FIXED_END: usize = 32;
    pub fn write(&self, out: &mut [u8], base: usize) -> Result<usize, i32> {
        if base + Self::FIXED_END > out.len() {
            return Err(ERR_OVERSIZE);
        }
        put_u32(out, base + 0, self.magic);
        put_u32(out, base + 4, self.version);
        put_u32(out, base + 8, self.order);
        put_u32(out, base + 12, self.taps);
        put_f32(out, base + 16, self.sample_rate);
        for i in 0..3 { put_u32(out, base + 20 + i * 4, self.reserved[i]); }
        let mut cur = base + Self::FIXED_END;
        Ok(cur - base)
    }
    pub fn read(buf: &[u8], base: usize) -> Result<(Self, usize), i32> {
        let limit = buf.len();
        Self::read_to(buf, base, limit)
    }
    fn read_to(buf: &[u8], base: usize, limit: usize) -> Result<(Self, usize), i32> {
        if base.checked_add(Self::FIXED_END).map_or(true, |e| e > limit) {
            return Err(ERR_TRUNCATED);
        }
        let magic = get_u32(buf, base + 0);
        let version = get_u32(buf, base + 4);
        let order = get_u32(buf, base + 8);
        let taps = get_u32(buf, base + 12);
        let sample_rate = get_f32(buf, base + 16);
        let reserved = { let mut a = [0 as u32; 3]; for i in 0..3 { a[i] = get_u32(buf, base + 20 + i * 4); } a };
        let mut cur = base + Self::FIXED_END;
        Ok((Self {
            magic,
            version,
            order,
            taps,
            sample_rate,
            reserved,
        }, cur - base))
    }
}

