pub const REPLAY_FLAGS_OVERFLOWED: u32 = 0x1;
/// first chunk of a REPLAY (begins with RESET)
pub const REPLAY_FLAGS_FIRST_CHUNK: u32 = 0x2;
/// last chunk of a REPLAY
pub const REPLAY_FLAGS_LAST_CHUNK: u32 = 0x4;
/// loop the clip
pub const PLAY_FLAGS_LOOP: u16 = 0x1;
/// a stream voice (STREAM_OPEN), not a clip
pub const PLAY_FLAGS_STREAM: u16 = 0x2;
/// report the playhead in STATUS
pub const PLAY_FLAGS_WANTS_PLAYHEAD: u16 = 0x4;
/// mixed (1) or virtual (0)
pub const PLAY_FLAGS_MIXED: u16 = 0x8;
/// spatialised; the panner applies
pub const PLAY_FLAGS_SPATIAL: u16 = 0x10;
/// 0 equal-power, 1 HRTF, 2 bed (ADR 0162 C1: the bus's bed slot, equal-power without one), 3 reserved; spatial voices only
pub const PLAY_FLAGS_PANNER_SHIFT: u32 = 5;
pub const PLAY_FLAGS_PANNER_MASK: u16 = 0x60;
/// a B-format clip or stream voice of 4, 9 or 16 channels (ADR 0162 C1); spatial, panner and dir are ignored; read from PLAY only
pub const PLAY_FLAGS_AMBISONIC: u16 = 0x80;
/// the voice starts with its fade ramp at 0, so an incoming stem is silent without touching gain; a stamped FADE to 1 opens it (ADR 0166 M4, API section 4.1); read from PLAY only
pub const PLAY_FLAGS_FADE_ZERO: u16 = 0x100;
/// start a voice; does not ramp
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Play {
    pub voice_id: u32,
    pub frame_offset: u32,
    /// clip id
    pub clip: u32,
    /// bus index
    pub bus: u16,
    pub flags: u16,
    pub group: u16,
    /// ADR 0166 M4: bits 0-9 groupId 1..=1023 (0 = ungated), bits 10-15 groupSize - 1 (PLAY_GATE_*; pack_gate); every member of a group arrives in one BATCH with the same frameOffset
    pub gate: u16,
    pub gain: f32,
    pub pitch: f32,
    pub dir_x: f32,
    pub dir_y: f32,
    pub dir_z: f32,
    pub lp_hz: f32,
    pub score: f32,
    pub start_offset_frames: u32,
}

impl Play {
    pub const FIXED_END: usize = 56;
    pub const OPCODE: u16 = 1; // PLAY
    pub fn write(&self, out: &mut [u8], base: usize) -> Result<usize, i32> {
        if base + Self::FIXED_END > out.len() {
            return Err(ERR_OVERSIZE);
        }
        put_u32(out, base + 12, self.clip);
        put_u16(out, base + 16, self.bus);
        put_u16(out, base + 18, self.flags);
        put_u16(out, base + 20, self.group);
        put_u16(out, base + 22, self.gate);
        put_f32(out, base + 24, self.gain);
        put_f32(out, base + 28, self.pitch);
        put_f32(out, base + 32, self.dir_x);
        put_f32(out, base + 36, self.dir_y);
        put_f32(out, base + 40, self.dir_z);
        put_f32(out, base + 44, self.lp_hz);
        put_f32(out, base + 48, self.score);
        put_u32(out, base + 52, self.start_offset_frames);
        let mut cur = base + Self::FIXED_END;
        let total = cur - base;
        if total % 4 != 0 || total / 4 > u16::MAX as usize {
            return Err(ERR_OVERSIZE);
        }
        put_u16(out, base + RecordHead::OPCODE_AT, Self::OPCODE);
        put_u16(out, base + RecordHead::WORDS_AT, (total / 4) as u16);
        put_u32(out, base + RecordHead::VOICE_ID_AT, self.voice_id);
        put_u32(out, base + RecordHead::FRAME_OFFSET_AT, self.frame_offset);
        Ok(cur - base)
    }
    pub fn read(buf: &[u8], base: usize) -> Result<(Self, usize), i32> {
        let (head, _) = RecordHead::read(buf, base)?;
        if head.opcode != Self::OPCODE {
            return Err(ERR_MALFORMED);
        }
        let limit = base + head.words as usize * 4;
        if limit > buf.len() {
            return Err(ERR_TRUNCATED);
        }
        Self::read_to(buf, base, limit)
    }
    fn read_to(buf: &[u8], base: usize, limit: usize) -> Result<(Self, usize), i32> {
        if base.checked_add(Self::FIXED_END).map_or(true, |e| e > limit) {
            return Err(ERR_TRUNCATED);
        }
        let (head, _) = RecordHead::read(buf, base)?;
        let clip = get_u32(buf, base + 12);
        let bus = get_u16(buf, base + 16);
        let flags = get_u16(buf, base + 18);
        let group = get_u16(buf, base + 20);
        let gate = get_u16(buf, base + 22);
        let gain = get_f32(buf, base + 24);
        let pitch = get_f32(buf, base + 28);
        let dir_x = get_f32(buf, base + 32);
        let dir_y = get_f32(buf, base + 36);
        let dir_z = get_f32(buf, base + 40);
        let lp_hz = get_f32(buf, base + 44);
        let score = get_f32(buf, base + 48);
        let start_offset_frames = get_u32(buf, base + 52);
        let mut cur = base + Self::FIXED_END;
        if cur > limit {
            return Err(ERR_MALFORMED);
        }
        let cur = limit; // appended words of a newer minor are skipped
        Ok((Self {
            voice_id: head.voice_id,
            frame_offset: head.frame_offset,
            clip,
            bus,
            flags,
            group,
            gate,
            gain,
            pitch,
            dir_x,
            dir_y,
            dir_z,
            lp_hz,
            score,
            start_offset_frames,
        }, cur - base))
    }
}

